def zs(X,tr): mu=X[tr].mean(0); sd=X[tr].std(0)+1e-6; return (X-mu)/sd/np.sqrt(X.shape[1])
def krr_multi(blocks, y, gammas, lams, seeds=(0,1,2), k=5):
    n=len(y); res={(g,l):[] for g in gammas for l in lams}
    for s in seeds:
        S={(g,l):np.zeros((n,8)) for g in gammas for l in lams}
        for te in folds(n,k,s,y):
            tr=np.setdiff1d(np.arange(n),te)
            Z=np.concatenate([zs(X,tr) for X in blocks],1)/np.sqrt(len(blocks)); sq=(Z**2).sum(1)
            D2=np.maximum(sq[:,None]+sq[None]-2*Z@Z.T,0); T=np.eye(8)[y[tr]]-1/8
            for g in gammas:
                K=np.exp(-g*D2); w,V=np.linalg.eigh(K[np.ix_(tr,tr)]); R=V.T@T; Kte=K[np.ix_(te,tr)]
                for l in lams: S[(g,l)][te]=Kte@(V@(R/(w+l)[:,None]))
        for key in S: res[key].append((S[key].argmax(1)==y).mean())
    return {k_:round(np.mean(v),4) for k_,v in res.items()}
